// === 需要你在导入后修改的配置 ===
// 1) 飞书多维表 app_token：如果多维表在知识库/wiki 中，填通过 wiki node token 换出来的 obj_token
const FEISHU_APP_TOKEN = 'EmPebJ3EAatSwusFGzLcDpkOnn0';
// 2) 飞书数据表 table_id
const FEISHU_TABLE_ID = 'tbleoohWAsivMCQt';


// 读取 Linear Webhook 的原始 body
const body = $('Webhook - Linear Issue 更新').first().json.body || {};

// Linear Issue webhook 通常形如：{ action, type, data: { issue fields... } }
const issue = body.data || body.issue || {};
const action = body.action || body.type || '';

const state = issue.state || issue.workflowState || {};
const stateName = state.name || issue.stateName || '';
const stateId = state.id || issue.stateId || '';
const stateType = state.type || '';

const issueId = issue.id || '';
const identifier = issue.identifier || '';
const issueUrl = issue.url || '';
const title = issue.title || '';

if (!identifier && !issueId) {
  throw new Error('Linear Webhook 中缺少 issue.identifier 和 issue.id，无法匹配飞书记录。');
}

const agentStatus = stateName || 'Unknown';

// 当前版本默认用飞书字段「Linear Issue ID」匹配 Linear identifier，例如 INS-32。
// 如果你后续新增了「Linear Issue UUID」字段，可以把 matchFieldName 改成 Linear Issue UUID，matchValue 改成 issueId。
return [
  {
    json: {
      raw: body,
      action,
      issueId,
      identifier,
      issueUrl,
      title,
      stateId,
      stateName,
      stateType,
      agentStatus,
      matchFieldName: 'Linear Issue ID',
      matchValue: identifier || issueId,
      config: {
        feishu_app_token: FEISHU_APP_TOKEN,
        feishu_table_id: FEISHU_TABLE_ID
      }
    }
  }
];

