parameters.jsCode:
const parsed = $('解析 Linear Webhook').first().json;
const searchResponse = $('飞书 - 查询对应记录').first().json;

const items = searchResponse.data?.items || [];
if (!items.length) {
  throw new Error(`没有在飞书多维表中找到 ${parsed.matchFieldName} = ${parsed.matchValue} 的记录。`);
}

const record = items[0];
const recordId = record.record_id;

return [
  {
    json: {
      ...parsed,
      feishu_record_id: recordId,
      feishuUpdateBody: {
        fields: {
          'Agent 状态': parsed.agentStatus,
          'Linear URL': parsed.issueUrl || undefined
        }
      }
    }
  }
];
